28	/// The runtime authority used to authorize IPC execution based on the Access Control List.
29	pub struct RuntimeAuthority {
30	  acl: BTreeMap<String, crate::utils::acl::manifest::Manifest>,
31	  allowed_commands: BTreeMap<CommandKey, ResolvedCommand>,
32	  denied_commands: BTreeMap<CommandKey, ResolvedCommand>,
33	  pub(crate) scope_manager: ScopeManager,
34	}
