36	/// The origin trying to access the IPC.
37	pub enum Origin {
38	  /// Local app origin.
39	  Local,
40	  /// Remote origin.
41	  Remote {
42	    /// Remote URL.
43	    url: String,
44	  },
45	}
46	
47	impl Display for Origin {
48	  fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
49	    match self {
50	      Self::Local => write!(f, "local"),
51	      Self::Remote { url } => write!(f, "remote: {url}"),
52	    }
53	  }
54	}
55	
56	impl Origin {
57	  fn matches(&self, context: &ExecutionContext) -> bool {
58	    match (self, context) {
59	      (Self::Local, ExecutionContext::Local) => true,
60	      (Self::Remote { url }, ExecutionContext::Remote { url: url_pattern }) => {
61	        url_pattern.matches(url)
62	      }
63	      _ => false,
64	    }
65	  }
66	}
