620	impl ScopeManager {
621	  pub(crate) fn get_global_scope_typed<R: Runtime, T: ScopeObject>(
622	    &self,
623	    app: &AppHandle<R>,
624	    key: &str,
625	  ) -> crate::Result<ScopeValue<T>> {
626	    match self.global_scope_cache.try_get::<ScopeValue<T>>() {
627	      Some(cached) => Ok(cached.clone()),
628	      None => {
629	        let mut allow: Vec<T> = Vec::new();
630	        let mut deny: Vec<T> = Vec::new();
631	
632	        if let Some(global_scope) = self.global_scope.get(key) {
633	          for allowed in &global_scope.allow {
634	            allow.push(
635	              T::deserialize(app, allowed.clone())
636	                .map_err(|e| crate::Error::CannotDeserializeScope(Box::new(e)))?,
637	            );
638	          }
639	          for denied in &global_scope.deny {
640	            deny.push(
641	              T::deserialize(app, denied.clone())
642	                .map_err(|e| crate::Error::CannotDeserializeScope(Box::new(e)))?,
643	            );
644	          }
645	        }
646	
647	        let scope = ScopeValue {
648	          allow: Arc::new(allow),
649	          deny: Arc::new(deny),
650	        };
651	        self.global_scope_cache.set(scope.clone());
652	        Ok(scope)
653	      }
654	    }
655	  }
