658	    &self,
659	    app: &AppHandle<R>,
660	    key: &ScopeKey,
661	  ) -> crate::Result<ScopeValue<T>> {
662	    let cache = self.command_cache.get(key).unwrap();
663	    match cache.try_get::<ScopeValue<T>>() {
664	      Some(cached) => Ok(cached.clone()),
665	      None => {
666	        let resolved_scope = self
667	          .command_scope
668	          .get(key)
669	          .unwrap_or_else(|| panic!("missing command scope for key {key}"));
670	
671	        let mut allow: Vec<T> = Vec::new();
672	        let mut deny: Vec<T> = Vec::new();
673	
674	        for allowed in &resolved_scope.allow {
675	          allow.push(
676	            T::deserialize(app, allowed.clone())
677	              .map_err(|e| crate::Error::CannotDeserializeScope(Box::new(e)))?,
678	          );
679	        }
680	        for denied in &resolved_scope.deny {
681	          deny.push(
682	            T::deserialize(app, denied.clone())
683	              .map_err(|e| crate::Error::CannotDeserializeScope(Box::new(e)))?,
684	          );
685	        }
686	
687	        let value = ScopeValue {
688	          allow: Arc::new(allow),
689	          deny: Arc::new(deny),
690	        };
691	
692	        let _ = cache.set(value.clone());
693	        Ok(value)
