+
+    let resolved_cmd = vec![ResolvedCommand {
+      windows: vec![Pattern::new(window).unwrap()],
+      context: ExecutionContext::Remote {
+        url: Pattern::new(url).unwrap(),
+      },
+      ..Default::default()
+    }];
+    let allowed_commands = [(command.to_string(), resolved_cmd.clone())]
+      .into_iter()
+      .collect();
+
+    let authority = RuntimeAuthority::new(
+      Default::default(),
+      Resolved {
+        allowed_commands,
+        ..Default::default()
+      },
+    );
+
+    assert_eq!(
+      authority.resolve_access(
+        command,
+        window,
+        webview,
+        &Origin::Remote {
+          url: url.replace('*', "studio")
+        }
+      ),
+      Some(resolved_cmd)
+    );
+  }
+
+  #[test]
+  fn remote_context_denied() {
+    let command = "my-command";
+    let window = "main";
+    let webview = "main";
+
+    let resolved_cmd = vec![ResolvedCommand {
+      windows: vec![Pattern::new(window).unwrap()],
+      ..Default::default()
+    }];
+    let allowed_commands = [(command.to_string(), resolved_cmd)].into_iter().collect();
+
+    let authority = RuntimeAuthority::new(
+      Default::default(),
+      Resolved {
+        allowed_commands,
+        ..Default::default()
+      },
+    );
+
+    assert!(authority
+      .resolve_access(
+        command,
+        window,
+        webview,
+        &Origin::Remote {
+          url: "https://tauri.app".into()
+        }
+      )
+      .is_none());
+  }
+
+  #[test]
+  fn denied_command_takes_precendence() {
+    let command = "my-command";
+    let window = "main";
+    let webview = "main";
+    let windows = vec![Pattern::new(window).unwrap()];
+    let allowed_commands = [(
+      command.to_string(),
+      vec![ResolvedCommand {
+        windows: windows.clone(),
+        ..Default::default()
+      }],
+    )]
+    .into_iter()
+    .collect();
+    let denied_commands = [(
+      command.to_string(),
+      vec![ResolvedCommand {
+        windows: windows.clone(),
+        ..Default::default()
+      }],
+    )]
+    .into_iter()
+    .collect();
+
+    let authority = RuntimeAuthority::new(
+      Default::default(),
+      Resolved {
+        allowed_commands,
+        denied_commands,
+        ..Default::default()
+      },
+    );
+
+    assert!(authority
+      .resolve_access(command, window, webview, &Origin::Local)
+      .is_none());
+  }
+}
